import {loadGlobal,makeGlobalMagneticLayer} from './global.mjs';
import {analyze,ranking,SERVICE} from './analysis.mjs';
import {loadGravity,analyzeGravity,makeGravityLayer} from './gravity.mjs';
import {LAYERS,gibsTemplate,findLatestFrame} from './weather-core.mjs';
const $=id=>document.getElementById(id),fmt=(v,n=1)=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:n,minimumFractionDigits:n}).format(v);
let data,type='positive',busy=false,mode='magnetic',gravityLayer,globalMagLayer,climateLayer,climatePending=false;
const configs={
 magnetic:{title:'Anomalias magnéticas',unit:'nT',source:'NOAA / EMAG2 v3',resolution:2,note:'Variações do campo magnético associadas à crosta terrestre. Valores positivos e negativos representam contrastes em relação ao campo de referência.',detail:'EMAG2 v3 da NOAA/NCEI, produto a 4 km de altitude, com resolução de 2 minutos de arco (cerca de 3,7 km no sentido norte–sul). É um modelo compilado de levantamentos e satélites, não uma medição em tempo real.',link:'https://www.ncei.noaa.gov/products/earth-magnetic-model-anomaly-grid-2',method:'Consultamos os centros das células da grade dentro do raio, com vizinho mais próximo. Distâncias usam a superfície esférica da Terra. Gradientes são calculados por diferenças centrais entre células vizinhas, em nT/km.',coverage:'Análise entre 85°S e 85°N.',legend:'Cores NOAA · escala não linear · <a href="https://www.ngdc.noaa.gov/geomag/data/EMAG2/EMAG2_scale.png" target="_blank" rel="noopener">ver escala em nT</a>'},
 gravity:{title:'Anomalias gravitacionais',unit:'mGal',source:'SCRIPPS / IGPP · v33.1',resolution:6,note:'Anomalia de ar livre: diferença entre a gravidade e um campo de referência, com correção de altitude. Pode refletir relevo e distribuição de massa; não é uma anomalia de Bouguer.',detail:'Grade Scripps/IGPP v33.1, distribuída pelo GMT, com EGM2008 em terra e altimetria por satélite nos oceanos. Espaçamento de 6 minutos de arco (cerca de 11,1 km norte–sul) e filtro gaussiano de 31,5 km. Cobertura entre 80°S e 80°N. Valores em mGal; 1 mGal = 0,00001 m/s². Modelo estático, sem monitoramento em tempo real.',link:'https://www.generic-mapping-tools.org/remote-datasets/earth-faa.html',method:'Analisamos os centros das células da grade de 6′ dentro do raio, sem inventar detalhe entre as células. Valores armazenados com passo de 0,1 mGal. Gradientes por diferenças centrais entre vizinhos, em mGal/km. A suavização de 31,5 km limita a interpretação de estruturas pequenas.',coverage:'Gravidade: cobertura entre 80°S e 80°N, sem os polos.',legend:'≤ −150 &nbsp; · &nbsp; 0 &nbsp; · &nbsp; ≥ +150 mGal · escala fixa; extremos saturados'},
 climate:{title:'Anomalias climáticas',unit:'°C',source:'NASA GIBS · GHRSST MUR',resolution:null,note:'Anomalia da temperatura da superfície do mar em relação à climatologia do produto: azul = mais frio, vermelho = mais quente que o normal. É um produto diário (não tempo real) e cobre só os oceanos. A temperatura média global desde 1880 está na seção “Clima global”.',detail:'GHRSST MUR L4, distribuído pela NASA GIBS, com anomalia diária da temperatura do mar. Publicado com ~1–2 dias de atraso. A climatologia de referência é a da própria fonte (ver metadados na NASA GIBS). Não há rankings por ponto neste modo.',link:'https://www.earthdata.nasa.gov/data/tools/gibs',method:'Neste modo o mapa mostra apenas a camada de satélite; não calculamos rankings nem gradientes. Para anomalias de tempo e comparação com o clima normal de um lugar, use a seção “Tempo e satélite”.',coverage:'Camada climática global (apenas oceanos).',legend:'Azul = mais frio · vermelho = mais quente que a climatologia da fonte · escala completa na NASA GIBS'}
};
const cfg=()=>configs[mode];
const map=L.map('map',{worldCopyJump:true,minZoom:0,maxZoom:15}).setView([-16.758611,-49.344444],7);
L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',maxZoom:19,referrerPolicy:'strict-origin-when-cross-origin'}).addTo(map);
const Magnetic=L.TileLayer.extend({getTileUrl(coords){const size=this.getTileSize(),nw=map.unproject(coords.scaleBy(size),coords.z),se=map.unproject(coords.add(L.point(1,1)).scaleBy(size),coords.z);return SERVICE+'/exportImage?'+new URLSearchParams({bbox:[nw.lng,se.lat,se.lng,nw.lat].join(','),bboxSR:'4326',imageSR:'3857',size:'256,256',format:'png32',transparent:'true',renderingRule:JSON.stringify({rasterFunction:'EMAG2_Color_Scale'}),f:'image'});}});
const magnetic=new Magnetic('',{opacity:.65,attribution:'NOAA/NCEI EMAG2 v3',maxZoom:15});let layerWarned=false;
magnetic.on('tileerror',()=>{if(mode==='magnetic'&&!layerWarned){layerWarned=true;status('A camada global está temporariamente indisponível. A análise numérica continua independente.',true);}});
const markers=L.layerGroup().addTo(map);let circle,center;
function status(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error);}
function selected(lat,lon){$('lat').value=lat.toFixed(6);$('lon').value=lon.toFixed(6);if(center)center.remove();center=L.circleMarker([lat,lon],{radius:7,color:'#fff',weight:3,fillColor:'#101b2b',fillOpacity:1}).addTo(map);}
function syncLayer(){magnetic.remove();gravityLayer?.remove();globalMagLayer?.remove();climateLayer?.remove();if(mode==='climate'){ensureClimate();if($('overlay').checked)climateLayer?.addTo(map);return;}if($('overlay').checked)(mode==='magnetic'?($('radius').value==='global'?globalMagLayer:magnetic):gravityLayer)?.addTo(map);}
// Camada climática: procura o dia mais recente realmente publicado na NASA GIBS; sem quadro, nada é exibido.
async function ensureClimate(){if(climateLayer||climatePending)return;climatePending=true;const layer=LAYERS.sst,probe=url=>new Promise(ok=>{const i=new Image(),t=setTimeout(()=>ok(false),8000);i.onload=()=>{clearTimeout(t);ok(true);};i.onerror=()=>{clearTimeout(t);ok(false);};i.src=url;});status('Procurando o dia mais recente da anomalia do mar…');
 try{const ms=await findLatestFrame(layer,probe,Date.now(),10);if(ms===null){status('A NASA GIBS não retornou a camada de anomalia do mar. Nada é exibido no lugar.',true);return;}climateLayer=L.tileLayer(gibsTemplate(layer,ms),{opacity:.8,maxNativeZoom:layer.nativeZoom,maxZoom:15,attribution:'NASA GIBS · GHRSST MUR'});if(mode==='climate'&&$('overlay').checked)climateLayer.addTo(map);status('Anomalia da temperatura do mar de '+new Date(ms).toISOString().slice(0,10)+' (UTC): produto diário, com ~1–2 dias de atraso.');}finally{climatePending=false;}}
function climateTexts(){$('scopeHint').textContent='A camada climática é global; análise por ponto e raio não se aplica. Veja também a seção “Clima global” no menu superior.';$('context').textContent='Modo climático: mapa de anomalia da temperatura do mar (diário). A série de temperatura global desde 1880 está na seção “Clima global”.';}
function clearResults(){data=undefined;markers.clearLayers();circle?.remove();circle=undefined;for(const id of ['min','max','count','range'])$(id).textContent='—';$('rows').replaceChildren();$('context').textContent='Escolha uma região para analisar.';$('download').disabled=true;}
function syncMode(){const c=cfg();document.body.dataset.mode=mode;$('mapTitle').textContent=c.title;$('sourceBadge').textContent=c.source;$('modeNote').textContent=c.note;$('sourceDetail').textContent=c.detail;$('sourceLink').href=c.link;$('methodDetail').textContent=c.method;$('coverageHint').textContent='Coordenadas decimais, ou clique no mapa. '+c.coverage;$('legendInfo').innerHTML=c.legend;$('overlayLabel').textContent=mode==='gravity'?'Camada gravitacional':mode==='climate'?'Camada climática':'Camada magnética';$('map').setAttribute('aria-label','Mapa interativo de '+c.title.toLowerCase());$('resolutionNote').textContent=mode==='gravity'?'Ar livre · grade de 6′ (~11 km) · suavização de 31,5 km':mode==='climate'?'GHRSST MUR · produto diário · somente oceanos':'EMAG2 v3 · grade de 2′ (~3,7 km) · altitude de 4 km';$('lat').min=mode==='gravity'?'-79.999999':'-85';$('lat').max=mode==='gravity'?'79.999999':'85';syncScope();if(mode==='climate')climateTexts();syncLayer();}
function syncScope(){const global=$('radius').value==='global';for(const id of ['lat','lon','locate'])$(id).disabled=busy||global;$('scopeHint').textContent=global?'Toda a Terra. As grades globais usam células de 6′ e suavização de 31,5 km; não são dados diários.':'Análise ao redor do ponto escolhido.';document.body.dataset.scope=global?'global':'regional';if(global&&mode==='magnetic'){$('resolutionNote').textContent='Global · EMAG2 v3 a 4 km · grade de 6′ · suavização de 31,5 km';$('legendInfo').textContent='≤ −500 · 0 · ≥ +500 nT · escala fixa; extremos saturados';$('sourceDetail').textContent='Visão global de EMAG2 v3 a 4 km, distribuída pelo GMT em grade de 6 minutos de arco, suavizada em 31,5 km. Ranking de toda a grade disponível; não equivale aos extremos da resolução original de 2′.';$('sourceLink').href='https://www.generic-mapping-tools.org/remote-datasets/earth-mag.html';$('methodDetail').textContent='Os rankings globais percorrem todas as células válidas da grade de 6′. Gradientes por diferenças centrais, em nT/km. Lacunas permanecem sem dados.';}}
map.on('click',e=>{if(busy||mode==='climate'||$('radius').value==='global')return;const lon=((e.latlng.lng+180)%360+360)%360-180;selected(Math.max(-85,Math.min(85,e.latlng.lat)),lon);status('Ponto selecionado. Clique em “Analisar região” para atualizar os resultados.');});$('overlay').onchange=syncLayer;
function popup(p,i){return `<b>Ponto ${i+1} · ${mode==='gravity'?'Gravidade':'Magnetismo'}</b><br>${fmt(p.lat,5)}, ${fmt(p.lon,5)}<br>Anomalia: <b>${fmt(p.value)} ${cfg().unit}</b><br>Distância: ${p.km===null?'—':fmt(p.km)+' km'}<br>Gradiente: ${Number.isFinite(p.gradient)?fmt(p.gradient)+' '+cfg().unit+'/km':'indisponível'}`;}
function renderRanking(){markers.clearLayers();$('rows').replaceChildren();const list=data.ranks?.[type]??ranking(data,type);for(const [i,p] of list.entries()){const marker=L.marker([p.lat,p.lon],{icon:L.divIcon({className:'',html:`<div class="marker">${i+1}</div>`,iconSize:[28,28],iconAnchor:[14,14]})}).addTo(markers).bindPopup(popup(p,i));const tr=document.createElement('tr');tr.innerHTML=`<td>${String(i+1).padStart(2,'0')}</td><td>${fmt(p.lat,5)}, ${fmt(p.lon,5)}</td><td>${p.km===null?'—':fmt(p.km)+' km'}</td><td>${fmt(p.value)} ${cfg().unit}</td><td>${Number.isFinite(p.gradient)?fmt(p.gradient)+' '+cfg().unit+'/km':'—'}</td><td><button aria-label="Ver ponto ${i+1} no mapa">Ver ↗</button></td>`;tr.querySelector('button').onclick=()=>{map.setView([p.lat,p.lon],10);marker.openPopup();$('map').scrollIntoView({behavior:'smooth',block:'center'});};$('rows').append(tr);}if(!list.length)$('rows').innerHTML='<tr><td colspan="6">Nenhum ponto disponível nesta categoria.</td></tr>';}
function render(){const global=data.scope==='global';circle?.remove();if(global){circle=undefined;center?.remove();center=undefined;map.fitBounds([[-80,-180],[80,180]]);}else{selected(data.lat,data.lon);circle=L.circle([data.lat,data.lon],{radius:data.radius*1000,color:'#183f49',weight:1.5,dashArray:'6 5',fillOpacity:.025}).addTo(map);map.fitBounds(circle.getBounds(),{padding:[15,15]});}let min=data.min??Infinity,max=data.max??-Infinity;if(!global)for(const p of data.points){min=Math.min(min,p.value);max=Math.max(max,p.value);}$('min').textContent=fmt(min)+' '+cfg().unit;$('max').textContent=fmt(max)+' '+cfg().unit;$('count').textContent=fmt(data.validCount??data.points.length,0);$('range').textContent=global?'Global':data.radius+' km';$('context').textContent=global?'Ranking mundial · grade de 6′ · '+fmt(data.validCount/data.total*100)+'% de células válidas · modelo estático':(mode==='gravity'?'Gravidade · ar livre':'Magnetismo')+' · Centro: '+fmt(data.lat,5)+', '+fmt(data.lon,5)+' · '+fmt(data.points.length/data.total*100)+'% das células com dados';$('download').disabled=false;$('download').textContent=global?'↓ Exportar ranking CSV':'↓ Exportar CSV';renderRanking();}
function setBusy(value){busy=value;for(const id of ['analyze','locate','home','mode','radius','lat','lon'])$(id).disabled=value;$('progress').hidden=!value;if(value)$('progress').value=0;syncScope();}
async function run(useCache=false){if(busy)return;if(mode==='climate'){status('Modo climático: camada de anomalia da temperatura do mar. Não há ranking por ponto; veja a seção “Clima global”.');return;}setBusy(true);const lat=Number($('lat').value),lon=Number($('lon').value),radius=$('radius').value==='global'?'global':Number($('radius').value);try{if(!Number.isFinite(lat)||Math.abs(lat)>85||!Number.isFinite(lon)||Math.abs(lon)>180)throw Error('Informe coordenadas válidas.');let next,cached;
 if(radius==='global'){status('Carregando a grade e os rankings de toda a Terra…');const result=await loadGlobal(mode);if(mode==='magnetic'&&!globalMagLayer)globalMagLayer=makeGlobalMagneticLayer(L,result.values);if(mode==='gravity'&&!gravityLayer)gravityLayer=makeGravityLayer(L,result.values);next=result.data;syncLayer();}
 else if(mode==='gravity'){status('Carregando grade gravitacional (13 MB na primeira abertura)…');const values=await loadGravity(p=>{$('progress').value=p;status(`Carregando gravidade: ${Math.round(p*100)}%…`);});if(!gravityLayer)gravityLayer=makeGravityLayer(L,values);syncLayer();next=analyzeGravity(values,lat,lon,radius);}
 else {status('Consultando a grade magnética oficial…');if(useCache&&Math.abs(lat+16.758611)<1e-6&&Math.abs(lon+49.344444)<1e-6&&radius===100){try{const r=await fetch('goiania.json');if(r.ok)cached=await r.json();}catch{}}next=cached??await analyze(lat,lon,radius,p=>{$('progress').value=p;status(`Consultando a NOAA: ${Math.round(p*100)}% concluído…`);});next.mode='magnetic';}
 data=next;render();status(data.scope==='global'?`Análise global: ${fmt(data.validCount,0)} células válidas. Os rankings mostram os 10 extremos de cada categoria.`:`Análise concluída. ${data.points.length} células válidas no raio de ${data.radius} km.${cached?' Consulta de Goiânia salva para abertura rápida.':''}`);
 }catch(e){status('Não foi possível concluir: '+e.message+(data?' Os resultados anteriores foram mantidos.':' Tente outra região ou novamente em alguns instantes.'),true);}finally{setBusy(false);}}
$('radius').onchange=()=>{clearResults();syncMode();run(true);};
$('mode').onchange=()=>{mode=$('mode').value;clearResults();syncMode();run(true);};
$('search').onsubmit=e=>{e.preventDefault();run();};$('home').onclick=()=>{selected(-16.758611,-49.344444);$('radius').value='100';syncMode();run(true);};$('locate').onclick=()=>{if(!navigator.geolocation){status('Este navegador não oferece localização.',true);return;}status('Obtendo sua localização…');navigator.geolocation.getCurrentPosition(p=>{selected(p.coords.latitude,p.coords.longitude);map.setView([p.coords.latitude,p.coords.longitude],8);status('Localização selecionada. Clique em “Analisar região”.');},()=>status('Não foi possível obter a localização. Você pode clicar no mapa ou informar coordenadas.',true),{timeout:15000});};
document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;document.querySelectorAll('[data-type]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',String(el===b));});if(data)renderRanking();});
$('download').onclick=()=>{if(!data)return;const c=configs[data.mode],rows=[['tipo','abrangencia','fonte','analise_utc','resolucao_arcmin','centro_lat','centro_lon','raio_km','latitude','longitude','distancia_km','anomalia_'+c.unit,'gradiente_'+c.unit+'_km'],...data.points.map(p=>[data.mode,data.scope??'regional',data.source??c.source,data.date,data.resolution_arcmin??c.resolution,data.lat,data.lon,data.radius,p.lat,p.lon,p.km,p.value,p.gradient??''])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`magneterra-${data.mode==='gravity'?'gravidade':'magnetismo'}-${data.scope??'regional'}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
syncMode();run(true);
window.magneTerraState=()=>({mode,data});
